import { useEffect, useState } from "react";

type Props = { appName?: string; projectId?: string; installId?: number; eventRevision?: number; widgetSize?: "half" | "full"; widgetSettings?: Record<string, unknown> };
type Step = { name: string; state: string; progress: number; kind: string; warning?: string };
type Item = { id:string; process_id:string; process_name:string; assignment_name?:string; target?:string; agent_id?:number; state:string; backend?:string; progress?:number; current_step?:string; created_at?:string; next_run_at?:string; needs_attention?:boolean; warning?:string; steps?:Step[]; steps_completed?:number; steps_total?:number };
type Data = { counts:{active:number;scheduled:number;attention:number;recent:number}; active:Item[]; upcoming:Item[]; recent:Item[]; live_steps:Step[]; warnings:string[]; partial:boolean };
const empty:Data={counts:{active:0,scheduled:0,attention:0,recent:0},active:[],upcoming:[],recent:[],live_steps:[],warnings:[],partial:false};
const label=(s:string)=>s.replaceAll("_"," ");
const when=(s?:string)=>s?new Date(s).toLocaleString(undefined,{dateStyle:"short",timeStyle:"short"}):"—";
export default function ProcessOverviewWidget(props:Props){
 const [data,setData]=useState(empty),[error,setError]=useState("");
 const load=()=>{const q=new URLSearchParams();if(props.projectId)q.set("project_id",props.projectId);if(props.installId)q.set("install_id",String(props.installId));return fetch(`/api/apps/${encodeURIComponent(props.appName||"processes")}/processes/overview?${q}`,{credentials:"same-origin"}).then(async r=>{if(!r.ok)throw new Error((await r.text())||`Request failed (${r.status})`);return r.json()}).then(d=>{setData({...empty,...d});setError("")}).catch(e=>setError(e instanceof Error?e.message:String(e)))};
 useEffect(()=>{void load()},[props.appName,props.projectId,props.installId,props.eventRevision]);
 const limit=Math.max(1,Math.min(12,Number(props.widgetSettings?.recent_limit??4))); const row=(x:Item)=><article className="ap-process-overview-row" key={`${x.process_id}:${x.id}`}><div className="ap-process-overview-main"><div className="ap-process-overview-title"><strong>{x.process_name}</strong><span className={`pill ${x.needs_attention?"blocked":x.state}`}>{label(x.state)}</span></div><div className="small muted">{x.assignment_name||x.backend||"Procedure"}{x.target?` · ${x.target}`:""}{x.current_step?` · ${x.current_step}`:""}{x.progress!=null?` · ${x.progress}%`:""}</div>{x.warning&&<div className="small notice">{x.warning}</div>}{x.steps_total? <div className="small muted">{x.steps_completed||0}/{x.steps_total} steps complete</div>:null}<a href={`/apps/${encodeURIComponent(props.appName||"processes")}/page?${new URLSearchParams({project_id:props.projectId||"",process_id:x.process_id,run_id:x.id})}`}>Open details ↗</a></div>{x.next_run_at&&<time className="small muted">{when(x.next_run_at)}</time>}</article>;
 return <section aria-label="Processes overview" className="ap-process-overview"><header className="row between"><div><h2>Processes</h2><p className="small muted">Live procedure execution overview</p></div><button type="button" onClick={()=>void load()}>Refresh</button></header>{error&&<p role="alert" className="notice">{error}</p>}<div className="ap-process-overview-stats"><span><b>{data.counts.active}</b> Active</span><span><b>{data.counts.scheduled}</b> Scheduled</span><span><b>{data.counts.attention}</b> Attention</span></div>{data.warnings.map(w=><p className="small muted" key={w}>{w}</p>)}<h3>Running and attention</h3>{data.active.slice(0,limit).map(row)}{!data.active.length&&<p className="small muted">Nothing running.</p>}<h3>Upcoming schedules</h3>{data.upcoming.slice(0,Math.min(4,limit)).map(row)}{!data.upcoming.length&&<p className="small muted">No upcoming schedules.</p>}<h3>Recent outcomes</h3>{data.recent.slice(0,limit).map(row)}{!data.recent.length&&<p className="small muted">No recent executions.</p>}</section>;
}
